-- Source-local period projection for retained books outside the recovery roster.
-- Exact existing native scope registry keys; no title inference.
ALTER TABLE current_acquisition_market ADD COLUMN display_period text GENERATED ALWAYS AS (
CASE WHEN source='kalshi' THEN CASE WHEN split_part(metadata->>'event_ticker','-',1) IN ('KXMLBF3') THEN 'first_3'
WHEN split_part(metadata->>'event_ticker','-',1) IN ('KXMLBF5','KXMLBF5SPREAD','KXMLBF5TOTAL') THEN 'first_5'
WHEN split_part(metadata->>'event_ticker','-',1) IN ('KXMLBGAME','KXMLBSPREAD','KXMLBTOTAL','KXNBAGAME','KXNBASPREAD','KXNBATOTAL','KXNCAAMBGAME','KXNCAAMBSPREAD','KXNCAAMBTOTAL','KXNCAAFGAME','KXNCAAFSPREAD','KXNCAAFTOTAL','KXNFLGAME','KXNFLSPREAD','KXNFLTOTAL','KXNHLGAME','KXNHLSPREAD','KXNHLTOTAL') THEN 'full_game'
WHEN split_part(metadata->>'event_ticker','-',1) IN ('KXMLBAL','KXMLBNL','KXMLB','KXNBAEAST','KXNBAWEST','KXNBA','KXNCAAMBA10','KXNCAAMBACC','KXNCAAMBACCREG','KXNCAAMBAE','KXNCAAMBAMER','KXNCAAMBASUN','KXNCAAMBBIG10','KXNCAAMBBIG10REG','KXNCAAMBBIG12','KXNCAAMBBIG12REG','KXNCAAMBBIGEAST','KXNCAAMBBIGEASTREG','KXNCAAMBBIGTENREG','KXNCAAMBBSKY','KXNCAAMBBSOU','KXNCAAMBBWEST','KXNCAAMBCAA','KXNCAAMBHL','KXNCAAMBHOR','KXNCAAMBIG12','KXNCAAMBIGEAST','KXNCAAMBIGTEN','KXNCAAMBIVY','KXNCAAMBMAA','KXNCAAMBMAMER','KXNCAAMBMEAC','KXNCAAMBMVAL','KXNCAAMBMW','KXNCAAMBNEC','KXNCAAMBOV','KXNCAAMBPAC12','KXNCAAMBPAT','KXNCAAMBSBELT','KXNCAAMBSEC','KXNCAAMBSECREG','KXNCAAMBSLC','KXNCAAMBSOCON','KXNCAAMBSUM','KXNCAAMBSUN','KXNCAAMBSWAC','KXNCAAMBUAC','KXNCAAMBUSA','KXNCAAMBWAC','KXNCAAMBWCC','KXMARMAD','KXNCAAFAAC','KXNCAAFACC','KXNCAAFB10','KXNCAAFB12','KXNCAAFBACC','KXNCAAFBB10','KXNCAAFBB12','KXNCAAFBSEC','KXNCAAFCUSA','KXNCAAFIVY','KXNCAAFMAC','KXNCAAFMWC','KXNCAAFPAC10','KXNCAAFPAC12','KXNCAAFSBELT','KXNCAAFSEC','KXNCAAF','KXNFLAFCCHAMP','KXNFLNFCCHAMP','KXSB','KXNHLEAST','KXNHLWEST','KXNHL') THEN 'season'
WHEN split_part(metadata->>'event_ticker','-',1) IN ('KXNBA1HWINNER','KXNBA1HSPREAD','KXNBA1HTOTAL','KXNCAAMB1HWINNER','KXNCAAMB1HSPREAD','KXNCAAMB1HTOTAL','KXNCAAF1H','KXNCAAF1HWINNER','KXNCAAF1HSPREAD','KXNCAAF1HTOTAL','KXNFL1H','KXNFL1HWINNER','KXNFL1HSPREAD','KXNFL1HTOTAL') THEN 'first_half' ELSE 'unknown' END
WHEN source='polymarket_us' AND metadata->>'sportsMarketType' IN ('baseball_team_full_game_spread','baseball_team_full_game_total','baseball_team_full_game_winner','basketball_team_full_game_spread','basketball_team_full_game_total','basketball_team_full_game_winner','football_team_full_game_spread','football_team_full_game_total','football_team_full_game_winner','hockey_team_full_game_spread','hockey_team_full_game_total','hockey_team_full_game_winner') THEN 'full_game' ELSE 'unknown' END) STORED;
